// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.prank(caller);
        try c.setOwner(newOwner) {} catch {}
        if (caller == c.owner()) {
            assertEq(c.owner(), newOwner, "owner should be newOwner if caller was owner");
        } else {
            assertTrue(true, "irrelevant when caller not owner");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.deal(actor, 0.1 ether);
        vm.prank(actor);
        vm.prank(actor);
        (bool ok,) = address(c).call(abi.encodeWithSelector(C.setOwner.selector, newOwner));
        assertTrue(c.owner() == actor);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != c.owner());
        vm.prank(actor);
        bool ok = true;
        try c.setOwner(actor) { ok = true; } catch { ok = false; }
        assertTrue((!ok) || (c.owner() == c.owner()));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(actor != c.owner());

        vm.prank(actor);
        c.setOwner(newOwner);

        assertTrue(c.owner() != newOwner);
    }
}
